// src/i18n.js
import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';

// 1. Ensure you are importing the English file:
import enTranslation from './locales/en/common.json'; 

const resources = {
  // 2. Ensure 'en' (your fallback language) is correctly defined:
  en: {
    translation: enTranslation, // The 'translation' is the default namespace
  },
  // fr: { translation: frTranslation }, // Add other languages here
};

i18n
  .use(initReactI18next)
  .init({
    resources,
    lng: 'en', // Force the default language to ensure it loads
    fallbackLng: 'en', 
    // ... other settings
  });

export default i18n;
